// Copy the Android launcher icons generated by `npm run tauri icon -- logo/mate-logo-square-bg.svg`
// (src-tauri/icons/android/) into the generated Android project's res/ folder, replacing Tauri's
// template icon: mipmap PNGs, the adaptive-icon XML, the ic_launcher_background colour, and removing
// the template drawables. Run via `npm run icons:android` after regenerating the icons.
import { cpSync, existsSync, readdirSync, rmSync, writeFileSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const src = join(root, "src-tauri", "icons", "android");
const res = join(root, "src-tauri", "gen", "android", "app", "src", "main", "res");

if (!existsSync(src) || !existsSync(res)) {
  console.error("copy-android-icons: icons/android or gen/android/.../res not found (run tauri icon and tauri android init)");
  process.exit(1);
}

for (const dir of readdirSync(src).filter((d) => d.startsWith("mipmap-"))) {
  cpSync(join(src, dir), join(res, dir), { recursive: true });
}

// Colour referenced by the adaptive icon (@color/ic_launcher_background), taken from the generated values file.
const bg = readFileSync(join(src, "values", "ic_launcher_background.xml"), "utf8").match(
  /<color name="ic_launcher_background">([^<]+)<\/color>/,
);
if (!bg) {
  console.error("copy-android-icons: ic_launcher_background colour not found in icons/android/values");
  process.exit(1);
}
const colorsPath = join(res, "values", "colors.xml");
let colors = readFileSync(colorsPath, "utf8");
colors = colors.replace(/\s*<color name="ic_launcher_background">[^<]*<\/color>/, "");
colors = colors.replace("</resources>", `    <color name="ic_launcher_background">${bg[1]}</color>\n</resources>`);
writeFileSync(colorsPath, colors);

for (const f of ["drawable/ic_launcher_background.xml", "drawable-v24/ic_launcher_foreground.xml"]) {
  rmSync(join(res, f), { force: true });
}
console.log("copy-android-icons: copied launcher icons into gen/android res/");
